def check():
    left = [0, 1, 2, 3, 4, 5]
    right = [6, 7, 8, 9, 10, 11]
    edges = []
    for u in left:
        for v in right:
            edges.append((min(u,v), max(u,v)))

    # check degrees
    degrees = {i: 0 for i in range(12)}
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1

    assert all(d >= 4 for d in degrees.values())

    # check required
    required = [(2,8), (1,9), (0,6), (3,10), (0,9), (3,9)]
    for r in required:
        assert (min(r), max(r)) in edges

    print(sorted(edges))

check()

